export function parseUnwrapAssetInstruction<TProgram extends string, TAccountMetas extends readonly AccountMeta[]>(
  instruction: Instruction<TProgram> & InstructionWithAccounts<TAccountMetas> & InstructionWithData<ReadonlyUint8Array>,
): ParsedUnwrapAssetInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 10,
    })
  }
  let accountIndex = 0
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!
    accountIndex += 1
    return accountMeta
  }
  return {
    programAddress: instruction.programAddress,
    accounts: {
      user: getNextAccount(),
      assetVault: getNextAccount(),
      vaultAuthority: getNextAccount(),
      underlyingMint: getNextAccount(),
      confidentialMint: getNextAccount(),
      userConfidential: getNextAccount(),
      vaultTokenAccount: getNextAccount(),
      userUnderlying: getNextAccount(),
      tokenProgram: getNextAccount(),
      token2022Program: getNextAccount(),
    },
    data: getUnwrapAssetInstructionDataDecoder().decode(instruction.data),
  }
}
